using System;using System.IO;using System.Linq;using System.Collections.Generic;using Autodesk.AutoCAD.Colors;using App=Autodesk.AutoCAD.ApplicationServices.Application;
namespace Tvxd.Meps {
 public sealed partial class WirePlugin010 {
  static WireCatalog061 catalog061;static string catalogRaw061;static string CatalogPath061{get{return Path.Combine(Plugin.LibraryRoot,"wire-menu.json");}}
  static string Hex061(int aci){int c=EntityColor.LookUpRgb((byte)aci);return "#"+(c&0xffffff).ToString("X6");}
  static void ReloadCatalog061(IList<WireStyle010> samples){catalog061=null;string raw=PipeRules057.Read(CatalogPath061);var data=raw==null?new WireCatalog061():WireCatalog061.Decode(raw);if(raw==null){foreach(var p in Standards012.Presets()){if(!data.groups.Contains(p.kind))data.groups.Add(p.kind);data.wires.Add(new WireChoice061{name=p.name,group=p.kind,presetLayer=p.layer,color=Hex061(p.aci),weight=p.weight,pattern="LIỀN"});}}
   foreach(var s in samples)if(!data.seenSamples.Contains(s.id)){if(!data.groups.Contains("MẪU ĐÃ LẤY"))data.groups.Add("MẪU ĐÃ LẤY");data.seenSamples.Add(s.id);string name=s.name;if(data.wires.Any(x=>x.group=="MẪU ĐÃ LẤY"&&x.name==name))name+=" · "+s.id.Substring(0,6);data.wires.Add(new WireChoice061{id=s.id,name=name,group="MẪU ĐÃ LẤY",sample=s,color=s.rgb?"#"+s.red.ToString("X2")+s.green.ToString("X2")+s.blue.ToString("X2"):Hex061(s.aci),weight=s.lineweight,pattern="GIỮ MẪU",scale=s.scale});}
   data.Validate();catalog061=data;catalogRaw061=raw;view.SetCatalog(data);view.SetStyles(new List<WireStyle010>());
  }
  static void ManageCatalog061(){if(Busy||(otherBusy!=null&&otherBusy()))throw new InvalidOperationException("HOÀN TẤT THAO TÁC ĐANG CHẠY TRƯỚC.");Reload();if(catalog061==null)throw new InvalidOperationException("CHƯA ĐỌC ĐƯỢC DANH MỤC DÂY.");using(var form=new WireCatalogUi061(catalog061,CatalogPath061,catalogRaw061)){App.ShowModalDialog(form);if(form.Saved)Reload();}}
  static void QueueChoice061(WireChoice061 selected){var r=NewRequest(null);var current=PipeRules057.Read(CatalogPath061);if(current!=catalogRaw061){Reload();throw new InvalidOperationException("DANH MỤC VỪA ĐỔI; CHỌN LẠI DÂY.");}var choice=catalog061.wires.Single(x=>x.id==selected.id);if(choice.presetLayer!=null&&Cable016.Find(choice.presetLayer)==null)throw new InvalidOperationException("MÃ CÁP GỐC KHÔNG HỢP LỆ.");if(choice.presetLayer!=null){var original=Standards012.Presets().Single(x=>x.layer==choice.presetLayer);if(choice.color.Equals(Hex061(original.aci),StringComparison.OrdinalIgnoreCase)&&choice.pattern=="LIỀN"&&choice.weight==original.weight&&choice.scale==1){QueuePreset(original);return;}}r.style=catalog061.Style(choice,r.units,r.doc.Database.Ltscale,r.settings);WireModel010.CheckSettings(r.style,r.settings);if(r.style.units!=r.units)throw new InvalidOperationException("ĐƠN VỊ BẢN VẼ KHÁC MẪU; CHƯA VẼ.");r.intent=new LastWire{style=Copy(r.style)};Start(r,"VẼ "+choice.name+". "+DrawHint);}
 }
}
